/*
 * Batik Coloring
 *
 *  Basic mode  - starts from the black-and-white contour. Brushing or filling
 *                uncovers the original colours underneath.
 *  Free mode   - the user picks colours and fills or paints the sections.
 *
 * Pattern data comes from patterns/<id>.js (generated by tools/make_pattern.py).
 * Everything runs in the browser; the final image is downloaded as a PNG.
 */
(function () {
  'use strict';

  const PALETTE = [
    '#1b1b1b', '#5b2a12', '#8a3d1b', '#b5562a', '#e08a3c', '#f2c46d', '#f6e7c1',
    '#ffffff', '#1f3a5f', '#3f7f6a', '#8fb996', '#7a9cc6', '#9b3d5e', '#c9a7d9'
  ];
  const MAX_UNDO = 20;
  const HINT = {
    basic: 'Brush over the drawing to uncover its original colours. Use "Fill section" to uncover a whole area at once.',
    free: 'Pick a colour, then tap an area to fill it or paint freely. Colour stays inside the lines.'
  };

  const $ = (id) => document.getElementById(id);
  const view = $('view');
  const vctx = view.getContext('2d');
  const sizeInput = $('size');
  const sizeOutput = $('size-value');
  const hint = $('hint');
  const undoBtn = $('undo');
  const clearBtn = $('clear');
  const customColor = $('custom-color');
  const registry = window.BATIK_PATTERNS || [];

  const loaded = new Map();   // pattern id -> prepared assets
  const layers = new Map();   // "<pattern>:<mode>" -> { canvas, ctx, undo[] }

  const app = {
    pattern: null,        // prepared assets of the pattern on screen
    mode: 'basic',        // 'basic' | 'free'
    tool: 'brush',        // 'brush' | 'fill' | 'eraser'
    color: '#b5562a'
  };

  // ---------------------------------------------------------------- helpers

  function makeCanvas(w, h) {
    const c = document.createElement('canvas');
    c.width = w;
    c.height = h;
    return c;
  }

  function loadImage(src) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error('Could not read the pattern image.'));
      img.src = src;
    });
  }

  function hexToRgb(hex) {
    const n = parseInt(hex.slice(1), 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }

  // Load a pattern once: line art, colour image and a per-pixel "is line" map.
  async function prepare(def) {
    if (loaded.has(def.id)) return loaded.get(def.id);

    const [lineImg, colorImg] = await Promise.all([loadImage(def.line), loadImage(def.color)]);
    const w = def.width;
    const h = def.height;

    const lineCanvas = makeCanvas(w, h);
    const lctx = lineCanvas.getContext('2d', { willReadFrequently: true });
    lctx.drawImage(lineImg, 0, 0, w, h);
    const lineData = lctx.getImageData(0, 0, w, h).data;

    const lines = new Uint8Array(w * h);
    for (let i = 0; i < lines.length; i++) lines[i] = lineData[i * 4 + 3] > 127 ? 1 : 0;

    const colorCanvas = makeCanvas(w, h);
    const cctx = colorCanvas.getContext('2d', { willReadFrequently: true });
    cctx.drawImage(colorImg, 0, 0, w, h);
    const colorData = cctx.getImageData(0, 0, w, h).data;

    const asset = { id: def.id, name: def.name, w, h, lineCanvas, colorCanvas, colorData, lines };
    loaded.set(def.id, asset);
    return asset;
  }

  // ---------------------------------------------------------------- layers
  // The layer holds only the user's colour work. The contour is drawn over it.

  function currentLayer() {
    const key = app.pattern.id + ':' + app.mode;
    let L = layers.get(key);
    if (!L) {
      const canvas = makeCanvas(app.pattern.w, app.pattern.h);
      L = { canvas, ctx: canvas.getContext('2d', { willReadFrequently: true }), undo: [] };
      layers.set(key, L);
    }
    return L;
  }

  function snapshot(L) {
    const copy = makeCanvas(L.canvas.width, L.canvas.height);
    copy.getContext('2d').drawImage(L.canvas, 0, 0);
    L.undo.push(copy);
    if (L.undo.length > MAX_UNDO) L.undo.shift();
  }

  function undo() {
    if (!app.pattern) return;
    const L = currentLayer();
    const prev = L.undo.pop();
    if (!prev) return;
    L.ctx.clearRect(0, 0, L.canvas.width, L.canvas.height);
    L.ctx.drawImage(prev, 0, 0);
    render();
    updateButtons();
  }

  function render() {
    const { w, h, lineCanvas } = app.pattern;
    vctx.fillStyle = '#ffffff';
    vctx.fillRect(0, 0, w, h);
    vctx.drawImage(currentLayer().canvas, 0, 0);
    vctx.drawImage(lineCanvas, 0, 0);
  }

  function updateButtons() {
    undoBtn.disabled = !app.pattern || currentLayer().undo.length === 0;
  }

  // ---------------------------------------------------------------- painting

  function configureBrush(ctx) {
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = Number(sizeInput.value);
    if (app.tool === 'eraser') {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.strokeStyle = '#000';
      ctx.fillStyle = '#000';
    } else {
      const style = app.mode === 'basic'
        ? ctx.createPattern(app.pattern.colorCanvas, 'no-repeat') // original colours
        : app.color;
      ctx.strokeStyle = style;
      ctx.fillStyle = style;
    }
  }

  function drawSegment(L, a, b) {
    const ctx = L.ctx;
    ctx.save();
    configureBrush(ctx);
    if (a.x === b.x && a.y === b.y) {
      // single tap: draw a dot
      ctx.beginPath();
      ctx.arc(a.x, a.y, ctx.lineWidth / 2, 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
    }
    ctx.restore();
  }

  // Flood-fill over the contour: returns a mask of the clicked section, or null.
  function sectionAt(x, y) {
    const { w, h, lines } = app.pattern;
    if (x < 0 || y < 0 || x >= w || y >= h) return null;
    const start = y * w + x;
    if (lines[start]) return null;

    const mask = new Uint8Array(w * h);
    const stack = new Int32Array(w * h);
    let sp = 0;
    const push = (j) => {
      if (!mask[j] && !lines[j]) {
        mask[j] = 1;
        stack[sp++] = j;
      }
    };
    push(start);
    while (sp > 0) {
      const i = stack[--sp];
      const px = i % w;
      if (px > 0) push(i - 1);
      if (px < w - 1) push(i + 1);
      if (i >= w) push(i - w);
      if (i < w * (h - 1)) push(i + w);
    }
    return mask;
  }

  function fillSection(L, mask) {
    const { w, h, colorData } = app.pattern;
    const img = L.ctx.getImageData(0, 0, w, h);
    const d = img.data;
    if (app.mode === 'basic') {
      for (let i = 0; i < mask.length; i++) {
        if (!mask[i]) continue;
        const k = i * 4;
        d[k] = colorData[k];
        d[k + 1] = colorData[k + 1];
        d[k + 2] = colorData[k + 2];
        d[k + 3] = 255;
      }
    } else {
      const [r, g, b] = hexToRgb(app.color);
      for (let i = 0; i < mask.length; i++) {
        if (!mask[i]) continue;
        const k = i * 4;
        d[k] = r;
        d[k + 1] = g;
        d[k + 2] = b;
        d[k + 3] = 255;
      }
    }
    L.ctx.putImageData(img, 0, 0);
  }

  function toCanvasPoint(e) {
    const r = view.getBoundingClientRect();
    return {
      x: (e.clientX - r.left) * (view.width / r.width),
      y: (e.clientY - r.top) * (view.height / r.height)
    };
  }

  let stroke = null;

  view.addEventListener('pointerdown', (e) => {
    if (!app.pattern) return;
    e.preventDefault();
    const p = toCanvasPoint(e);
    const L = currentLayer();

    if (app.tool === 'fill') {
      const mask = sectionAt(Math.floor(p.x), Math.floor(p.y));
      if (!mask) return;
      snapshot(L);
      fillSection(L, mask);
      render();
      updateButtons();
      return;
    }

    snapshot(L);
    updateButtons();
    stroke = { L, last: p };
    view.setPointerCapture(e.pointerId);
    drawSegment(L, p, p);
    render();
  });

  view.addEventListener('pointermove', (e) => {
    if (!stroke) return;
    const p = toCanvasPoint(e);
    drawSegment(stroke.L, stroke.last, p);
    stroke.last = p;
    render();
  });

  const endStroke = () => { stroke = null; };
  view.addEventListener('pointerup', endStroke);
  view.addEventListener('pointercancel', endStroke);

  function fillLayer(source) {
    const L = currentLayer();
    snapshot(L);
    L.ctx.clearRect(0, 0, L.canvas.width, L.canvas.height);
    if (source) L.ctx.drawImage(source, 0, 0);
    render();
    updateButtons();
  }

  // ---------------------------------------------------------------- UI state

  function setTool(tool) {
    app.tool = tool;
    document.querySelectorAll('.tool-btn').forEach((b) => {
      b.classList.toggle('active', b.dataset.tool === tool);
    });
    view.classList.toggle('brush-cursor', tool === 'brush');
  }

  function setColor(hex) {
    app.color = hex;
    customColor.value = hex;
    document.querySelectorAll('.swatch').forEach((s) => {
      s.classList.toggle('active', s.dataset.color === hex);
    });
    if (app.tool === 'eraser') setTool('brush');
  }

  function buildSwatches() {
    const box = $('swatches');
    PALETTE.forEach((hex) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'swatch';
      b.dataset.color = hex;
      b.style.background = hex;
      b.title = hex;
      b.setAttribute('aria-label', 'Colour ' + hex);
      b.addEventListener('click', () => setColor(hex));
      box.appendChild(b);
    });
  }

  function setMode(mode) {
    app.mode = mode;
    document.querySelectorAll('.mode-btn').forEach((b) => {
      b.classList.toggle('active', b.dataset.mode === mode);
    });
    $('basic-tools').hidden = mode !== 'basic';
    $('free-tools').hidden = mode !== 'free';
    clearBtn.textContent = mode === 'basic' ? 'Reset' : 'Clear';
    hint.textContent = HINT[mode];
    if (app.tool === 'eraser' && mode === 'basic') setTool('brush');
    if (app.pattern) render();
    updateButtons();
  }

  async function selectPattern(id) {
    const def = registry.find((p) => p.id === id);
    if (!def) return;
    hint.textContent = 'Loading pattern…';
    try {
      app.pattern = await prepare(def);
    } catch (err) {
      hint.textContent = err.message;
      return;
    }
    view.width = app.pattern.w;
    view.height = app.pattern.h;
    setMode(app.mode);
  }

  // ---------------------------------------------------------------- download

  function download() {
    if (!app.pattern) return;
    render();
    view.toBlob((blob) => {
      if (!blob) {
        hint.textContent = 'Sorry, the image could not be prepared for download.';
        return;
      }
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'batik-' + app.pattern.id + '-' + app.mode + '.png';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 2000);
    }, 'image/png');
  }

  // ---------------------------------------------------------------- init

  function init() {
    buildSwatches();
    setColor(app.color);
    setTool(app.tool);
    setMode(app.mode);

    sizeOutput.textContent = sizeInput.value;
    sizeInput.addEventListener('input', () => { sizeOutput.textContent = sizeInput.value; });

    document.querySelectorAll('.mode-btn').forEach((b) => {
      b.addEventListener('click', () => setMode(b.dataset.mode));
    });
    document.querySelectorAll('.tool-btn').forEach((b) => {
      b.addEventListener('click', () => setTool(b.dataset.tool));
    });
    customColor.addEventListener('input', (e) => setColor(e.target.value));

    $('reveal-all').addEventListener('click', () => fillLayer(app.pattern && app.pattern.colorCanvas));
    clearBtn.addEventListener('click', () => fillLayer(null));
    undoBtn.addEventListener('click', undo);
    $('download').addEventListener('click', download);

    document.addEventListener('keydown', (e) => {
      if ((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        undo();
      }
    });

    const select = $('pattern');
    if (!registry.length) {
      hint.textContent = 'No patterns found. Generate one with tools/make_pattern.py.';
      return;
    }
    registry.forEach((p) => select.add(new Option(p.name, p.id)));
    select.addEventListener('change', () => selectPattern(select.value));
    selectPattern(registry[0].id);
  }

  init();
})();
